/* From Uiverse.io by vinodjangid07 - Tags: gradient, button, chat, hover effect */
.__UIV_SCOPE__ .chatBtn {
  width: 55px;
  height: 55px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  border: none;
  background-color: #FFE53B;
  background-image: linear-gradient(147deg, #FFE53B, #FF2525,#FFE53B);
  cursor: pointer;
  padding-top: 3px;
  box-shadow: 5px 5px 10px rgba(0, 0, 0, 0.164);
  position: relative;
  background-size: 300%;
  background-position: left;
  transition-duration: 1s;
}

.__UIV_SCOPE__ .tooltip {
  position: absolute;
  top: -40px;
  opacity: 0;
  background-color: rgb(255, 180, 82);
  color: white;
  padding: 5px 10px;
  border-radius: 5px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition-duration: .5s;
  pointer-events: none;
  letter-spacing: 0.5px;
}

.__UIV_SCOPE__ .chatBtn:hover .tooltip {
  opacity: 1;
  transition-duration: .5s;
}

.__UIV_SCOPE__ .chatBtn:hover {
  background-position: right;
  transition-duration: 1s;
}
